onClick:
{{
  (async () => {
    const idBL = Get_Facture_ById.data[0]?.ID_BL;
    const numFacture = Get_Facture_ById.data[0]?.Numero_Facture_Pennylane || "";

    if (!idBL) {
      showAlert("Identifiant du bon de livraison introuvable.", "error");
      return;
    }

    try {
      // 1. Remise à zéro en base de données (Statut -> "À Facturer")
      await Reset_BL_A_Facturer.run({ id_bl: idBL });

      // 2. Alerte de rappel pour Pennylane
      showAlert("BL remis en « À Facturer ». Pense à archiver la facture " + numFacture + " dans Pennylane.", "warning");

      // 3. Redirection vers la fiche du Bon de Livraison
      await navigateTo("Détail Bon de Livraison", { id: idBL });
    } catch (err) {
      showAlert("Erreur lors de la réinitialisation : " + err.message, "error");
    }
  })()
}}
